using System.Diagnostics;
using System.Text.Json;
using DropSpace.Core.Lyrics;
using DropSpace.Core.Models;
using DropSpace.Infrastructure.Lyrics;
var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
var cache = new AiLyricsCache(root);
var coordinator = new PlainHyLyricsCoordinator(cache);
var source = new LyricsDocument(new[] {"chorus", "verse one", "chorus", "verse two", "chorus", "verse one", "chorus", "verse two"}.Select((text,id) => new LyricsLine(TimeSpan.FromSeconds(id), TimeSpan.FromSeconds(id+1), text, null, [])).ToArray(), LyricsProviderKind.LocalLrc);
var query = new LyricsQuery("fixture", "fixture", "fixture", TimeSpan.FromSeconds(8));
var identity = PlainHyLyricsProtocol.InferenceIdentity(new string('a',64));
var calls = 0;
var start = Stopwatch.GetTimestamp();
var result = await coordinator.TranslateAsync(query, source, "en", identity, cache.Generation, async (prompt, token) => { calls++; await Task.Delay(20, token); return "translated " + prompt[(prompt.IndexOf('\n') + 1)..]; }, default);
Console.WriteLine(JsonSerializer.Serialize(new { experiment = "eight-lines-three-exact-prompts", calls, elapsedMilliseconds = Stopwatch.GetElapsedTime(start).TotalMilliseconds, outcome = result.Outcome.ToString(), validIds = result.Document.Lines.Select((line,id) => line.Start == source.Lines[id].Start && line.End == source.Lines[id].End && line.Secondary != null).All(x => x), nativeModelRun = false, simulatedCallDelayMs = 20 }));
Directory.Delete(root, true);
